  const exportarNotaTXTCarpeta = async (nota) => {
    try {
      // Extraer texto plano del HTML
      const tempDiv = document.createElement("div");
      tempDiv.innerHTML = nota.contenido;
      const textoPlano = tempDiv.textContent || tempDiv.innerText;

      const contenidoTxt = `${nota.titulo}\n${"=".repeat(nota.titulo.length)}\n\n${textoPlano}`;

      // Enviar al backend para guardar en la carpeta real
      const response = await fetch(`${API_URL}/api/guardar-nota-txt`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          carpeta: nota.carpeta || "",
          nombreArchivo: `${nota.titulo.replace(/[^a-z0-9]/gi, "_")}.txt`,
          contenido: contenidoTxt,
        }),
      });

      if (response.ok) {
        setMensaje({
          tipo: "success",
          texto: "📄 Nota guardada como TXT en la carpeta",
        });
      } else {
        throw new Error("Error al guardar");
      }
    } catch (error) {
      setMensaje({
        tipo: "error",
        texto: "❌ Error al guardar TXT",
      });
    }
  };

  const exportarNotaPDF = (nota) => {
    // Crear un iframe oculto con el contenido
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(`
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="UTF-8">
          <title>${nota.titulo}</title>
          <style>
            body {
              font-family: Arial, sans-serif;
              max-width: 800px;
              margin: 40px auto;
              padding: 20px;
              line-height: 1.6;
            }
            h1 {
              color: #333;
              border-bottom: 2px solid #646cff;
              padding-bottom: 10px;
            }
            img {
              max-width: 100%;
              height: auto;
            }
          </style>
        </head>
        <body>
          <h1>${nota.titulo}</h1>
          ${nota.contenido}
        </body>
      </html>
    `);
    iframeDoc.close();

    // Esperar a que cargue y luego imprimir
    setTimeout(() => {
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    }, 500);

    setMensaje({
      tipo: "info",
      texto: "📄 Abriendo diálogo de impresión (Guardar como PDF)",
    });
  };

  // Función para instalar modelo GGUF en Ollama
  const instalarModeloOllama = async () => {
    if (!archivoModeloGGUF) {
      setMensaje({ tipo: "error", texto: "⚠️ Selecciona un archivo .gguf" });
      return;
    }

    if (!nombreModeloNuevo.trim()) {
      setMensaje({
        tipo: "error",
        texto: "⚠️ Ingresa un nombre para el modelo",
      });
      return;
    }

    setInstalandoModelo(true);

    try {
      const formData = new FormData();
      formData.append("archivo", archivoModeloGGUF);
      formData.append("nombre_modelo", nombreModeloNuevo);

      const response = await fetch(`${API_URL}/api/ollama/install-model`, {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Error instalando modelo");
      }

      const data = await response.json();

      setMensaje({
        tipo: "exito",
        texto: `✅ Modelo '${nombreModeloNuevo}' instalado exitosamente`,
      });

      // Actualizar lista de modelos
      if (data.modelos_disponibles) {
        setModelosDisponibles(data.modelos_disponibles);
      }

      // Activar automáticamente el modelo recién instalado
      try {
        const responseMotor = await fetch(`${API_URL}/api/motor/cambiar`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            usar_ollama: true,
            modelo_ollama: nombreModeloNuevo,
            n_gpu_layers: 35,
          }),
        });
        const dataMotor = await responseMotor.json();

        if (dataMotor.success) {
          setMensaje({
            tipo: "exito",
            texto: `✅ Modelo ${nombreModeloNuevo} instalado y activado con GPU`,
          });
        } else {
          console.warn("No se pudo activar automáticamente:", dataMotor);
        }
      } catch (errorActivacion) {
        console.warn("Error al activar automáticamente:", errorActivacion);
      }

      // Cerrar modal y limpiar
      setModalInstaladorModelo(false);
      setArchivoModeloGGUF(null);
      setNombreModeloNuevo("");

      // Recargar configuración
      cargarConfiguracion();
    } catch (error) {
      console.error("Error instalando modelo:", error);
      setMensaje({
        tipo: "error",
        texto: `❌ Error: ${error.message}`,
      });
    } finally {
      setInstalandoModelo(false);
    }
  };

