                                background:
                                  indiceFlashcardActual ===
                                  flashcardsSesion.length - 1
                                    ? "rgba(100, 100, 100, 0.3)"
                                    : "rgba(59, 130, 246, 0.2)",
                                border:
                                  indiceFlashcardActual ===
                                  flashcardsSesion.length - 1
                                    ? "1px solid rgba(100, 100, 100, 0.3)"
                                    : "1px solid rgba(59, 130, 246, 0.5)",
                                color:
                                  indiceFlashcardActual ===
                                  flashcardsSesion.length - 1
                                    ? "#666"
                                    : "#93c5fd",
                                cursor:
                                  indiceFlashcardActual ===
                                  flashcardsSesion.length - 1
                                    ? "not-allowed"
                                    : "pointer",
                                fontSize: "0.9rem",
                                fontWeight: "500",
                                transition: "all 0.2s",
