                                                  const response = await fetch(
                                                    `${API_URL}/api/subir-imagen-nota`,
                                                    {
                                                      method: "POST",
                                                      body: formData,
                                                    },
                                                  );

                                                  let imgSrc;
                                                  if (response.ok) {
                                                    const data =
                                                      await response.json();
                                                    imgSrc = `${API_URL}${data.url}`;
                                                  } else {
                                                    imgSrc = await new Promise(
                                                      (resolve) => {
                                                        const reader =
                                                          new FileReader();
                                                        reader.onload = (ev) =>
                                                          resolve(
                                                            ev.target.result,
                                                          );
                                                        reader.readAsDataURL(
                                                          file,
                                                        );
                                                      },
                                                    );
                                                  }

                                                  editorRef.current.focus();
                                                  const imgId =
                                                    "img_" + Date.now();
