                      color: "white",
                      fontWeight: "600",
                      fontSize: "1rem",
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      gap: "0.5rem",
                      transition: "transform 0.2s, box-shadow 0.2s",
