                const rutaNormalizada = (rutaFlashcardsActual || "").replace(
                  /\\/g,
                  "/",
                );
                const flashcardsEnRuta = flashcardsActuales.filter((f) => {
                  const carpetaFlashcard = (f.carpeta || "").replace(
                    /\\/g,
                    "/",
                  );
                  return carpetaFlashcard === rutaNormalizada;
                });
